package io.github.hienpham0344.stayfinder.review.controller;
import io.github.hienpham0344.stayfinder.review.service.ReviewService;import io.github.hienpham0344.stayfinder.review.dto.*;import io.github.hienpham0344.stayfinder.common.response.*;import io.github.hienpham0344.stayfinder.common.exception.*;import io.github.hienpham0344.stayfinder.security.CurrentUser;
import org.springframework.web.bind.annotation.*;import org.springframework.http.ResponseEntity;import org.springframework.data.domain.*;import jakarta.validation.Valid;import java.util.UUID;
@RestController public class ReviewController{
 private final ReviewService service;public ReviewController(ReviewService service){this.service=service;}
 @GetMapping("/api/accommodations/{id}/reviews")public ResponseEntity<ApiResponse<PageResponse<ReviewResponse>>> list(@PathVariable UUID id,@RequestParam(required=false)Integer star,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){if(page<0||size<1||size>100||star!=null&&(star<1||star>5))throw new BusinessException(ErrorCode.VALIDATION_ERROR);return ResponseEntity.ok(ApiResponse.success(service.list(id,star,PageRequest.of(page,size,Sort.by(Sort.Order.desc("createdAt"),Sort.Order.desc("id"))),CurrentUser.optional().map(CurrentUser::id).orElse(null))));}
 @GetMapping("/api/accommodations/{id}/reviews/summary")public ResponseEntity<ApiResponse<ReviewSummary>> summary(@PathVariable UUID id){return ResponseEntity.ok(ApiResponse.success(service.summary(id)));}
 @PostMapping("/api/accommodations/{id}/reviews")public ResponseEntity<ApiResponse<ReviewResponse>> create(@PathVariable UUID id,@Valid @RequestBody CreateReviewRequest request){return ResponseEntity.ok(ApiResponse.success(service.create(CurrentUser.require().id(),id,request)));}
 @PatchMapping("/api/reviews/{id}")public ResponseEntity<ApiResponse<ReviewResponse>> update(@PathVariable UUID id,@Valid @RequestBody UpdateReviewRequest request){return ResponseEntity.ok(ApiResponse.success(service.update(CurrentUser.require().id(),id,request)));}
 @DeleteMapping("/api/reviews/{id}")public ResponseEntity<ApiResponse<Void>> delete(@PathVariable UUID id){service.delete(CurrentUser.require().id(),id);return ResponseEntity.ok(ApiResponse.success(null));}
}
